function validate([head, nums]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 10000) return 'The list needs 1 to 10000 nodes.';
  const n = head.length;
  if (head.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each node value is an integer from 0 to n - 1.';
  if (new Set(head).size !== n) return 'Node values must be distinct.';
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > n) return 'nums needs 1 to n values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each value in nums is an integer from 0 to n - 1.';
  if (new Set(nums).size !== nums.length) return 'Values in nums must be distinct.';
  return null;
}

