function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const shuffle = (arr) => {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  };
  const list = shuffle(Array.from({ length: n }, (_, i) => i));
  const density = [0.2, 0.5, 0.8, 1][Math.floor(rand() * 4)];
  let nums = list.filter(() => rand() < density);
  if (nums.length === 0) nums = [list[Math.floor(rand() * n)]];
  return [list, shuffle(nums)];
}
